    //Primitive//
    public static final MultiblockMachineDefinition LARGE_COKE_OVEN = REGISTRATE
            .multiblock("large_coke_oven", LargeCokeOven::new)
            .rotationState(RotationState.ALL)
            .recipeType(GTRecipeTypes.COKE_OVEN_RECIPES)
            .recipeModifier(LargeCokeOven::recipeModifier, true)
            .appearanceBlock(CASING_COKE_BRICKS)
            .tooltips(CommonMachineTooltips.LARGE_PRIMITIVE_MACHINE)
            .pattern(definition -> FactoryBlockPattern.start()
                    .aisle(" AAA ", " BBB ", " BBB ", " BBB ")
                    .aisle("ABBBA", "B###B", "B###B", "BBBBB")
                    .aisle("ABBBA", "B###B", "B###B", "BBBBB")
                    .aisle("ABBBA", "B###B", "B###B", "BBBBB")
                    .aisle(" AAA ", " BcB ", " BBB ", " BBB ")
                    .where(' ', any())
                    .where('#', air())
                    .where('c', controller(blocks(definition.getBlock())))
                    .where('A', blocks(FIREBOX_BRONZE.get()))
                    .where('B', blocks(CASING_COKE_BRICKS.get()).or(blocks(COKE_OVEN_HATCH.get()).setMaxGlobalLimited(5)))
                    .build())
            .workableCasingModel(GTCEu.id("block/casings/solid/machine_coke_bricks"),
                    GTCEu.id("block/multiblock/coke_oven"))
            .register();

